from __future__ import annotations
import base64, shutil
from datetime import datetime
from pathlib import Path

MODULE="alliance_autonomous_student_v436.py"
REG="alliance_optional_property_modules.py"
DATA=""

def chk(p): compile(p.read_text(encoding="utf-8"),str(p),"exec")

def main():
    r=Path.cwd()
    req=["alliance_autonomous_student_v435.py","alliance_truth_integrity_v426.py",
         "alliance_autonomous_student_v434.py","alliance_autonomous_student_v433.py",
         "alliance_autonomous_student_v432.py","alliance_autonomous_student_v431.py",
         "alliance_autonomous_student_v430.py","alliance_cre_academy_v402.py",REG]
    miss=[x for x in req if not (r/x).exists()]
    if miss: raise SystemExit("Missing cumulative files: "+", ".join(miss))

    v435=(r/"alliance_autonomous_student_v435.py").read_text(encoding="utf-8")
    if 'VERSION="4.3.5-ALLIANCE-STUDENT-TRUTH-INTEGRITY-REPAIR"' not in v435:
        raise SystemExit("Unexpected 4.3.5 baseline. Refusing install.")

    (r/MODULE).write_text(base64.b64decode(DATA).decode(),encoding="utf-8")
    chk(r/MODULE)

    reg=r/REG; old=reg.read_text(encoding="utf-8")
    bak=r/f"{REG}.before-v436-{datetime.now().strftime('%Y%m%d-%H%M%S')}.bak"
    shutil.copy2(reg,bak)
    marker="# FOUNDATION 4.3.6 - Demand Contract Closure"
    if marker not in old:
        pos=old.rfind("    return result")
        if pos<0: raise SystemExit("Registrar return not found.")
        block=r"""
    # FOUNDATION 4.3.6 - Demand Contract Closure
    # Training only. Fresh V5 is not frozen here.
    try:
        if _route_exists(app, "/api/property-brain/autonomous-v436/status"):
            result["autonomous_v436"] = {"status":"ALREADY_REGISTERED","route":"/property-brain/autonomous-v436","error":None}
        else:
            import alliance_autonomous_student_v436 as v436
            result["autonomous_v436"] = {**v436.register(core), "error": None}
    except Exception as exc:
        result["autonomous_v436"] = {"status":"ERROR","error":f"{type(exc).__name__}: {exc}","fail_safe":True}

"""
        reg.write_text(old[:pos]+block+old[pos:],encoding="utf-8")
    chk(reg)

    print("Alliance Student 4.3.6 installed")
    print("Fix: demand-contract class ownership + transaction abstention discipline")
    print("4.3.5 truth-integrity layer preserved")
    print("V5 freeze: 0")
    print("Production/WhatsApp/Gold writes: 0")
    print("Dashboard: /property-brain/autonomous-v436")
    print("Backup:",bak)

if __name__=="__main__": main()
